 ("global KV payload",
  ' <div class="scene-scale"><span class="scale-glyph"/><span>1 cubic unit = 1 GB <em>${s.view===\'cache\'?\'context memory arithmetic\':\'audited weight payload\'} / ${this.engine&&this.engine.renderer.software?\'CPU 3D\':\'WebGL2\'}</em></span></div><div class="scene-legend">${(s.view===\'cache\'?[[\'full\',\'Compressed KV\'],[\'linear\',\'Recurrent state\']]:s.view===\'storage\'?[[\'expert\',\'Experts\'],[\'index\',\'Indexer\'],[\'mtp\',\'MTP\']]:[[\'full\',\'Sparse MLA\'],[\'linear\',\'Gated linear\']]).map(([key,l])=>html`<span><i style=${{background:COL[key]}}/>${l}</span>`)}</div>'),
