 ("function moduleExplanation(m){",
  ' function moduleExplanation(m){if(!m)return EXP.overview;if(m.mode)return EXP[m.mode];if(m.id===\'vision\')return EXP.vision;if(m.id===\'D0\')return EXP.mtp;if(m.id===\'embed\')return {title:\'Token embedding.\',body:\'A 154,880-row table at hidden 4,096, untied from the output head, so both tables exist on disk. It keeps a high-precision dtype in both quantized builds.\'};if(m.id===\'head\')return {title:\'Output head, untied.\',body:\'4,096 \\u2192 154,880 logits, separate from the embedding, and one of the modules the quantization configs exclude.\'};return EXP.overview;}'),
