 ("function resolveAuditModule(name){",
  ' function resolveAuditModule(name){let n=name.replace(/^(?:language_model\\.|model\\.)+/,\'\');let a=n.match(/^layers\\.(\\d+)\\./);if(a)return (+a[1])<=44?\'L\'+a[1]:\'D0\';if(/^mtp\\./.test(n))return \'D0\';if(/^model\\.language_model\\.layers|^language_model\\.model\\.layers/.test(n)){let b=n.match(/^.*?layers\\.(\\d+)\\./);if(b)return (+b[1])<=44?\'L\'+b[1]:\'D0\';}if(/^(model\\.)?visual|^visual\\./.test(n))return \'vision\';if(/embed_tokens/.test(n))return \'embed\';if(/^(model\\.)?language_model\\.norm|^norm\\.|lm_head/.test(n))return \'head\';return \'Unmapped\';}'),
